  area(arg1: Shape): number;
  firstWord(arg1: string | null): string | null;
  double(arg1: bigint): bigint;
  /** Fails with PlumeError<AppErrors["divide"]>. */
  divide(arg1: number, arg2: number): number;
  /** Fails with PlumeError<AppErrors["slowSquare"]>. */
